 const ranked=(name,point)=>entries.filter(e=>name&&e.garden===name).sort((a,b)=>(a.id.endsWith('-tile-0-0')||a.id.endsWith('-tile-0--1')?-100000:0)+new T.Vector3(...a.position).distanceToSquared(point||new T.Vector3())-(b.id.endsWith('-tile-0-0')||b.id.endsWith('-tile-0--1')?-100000:0)-new T.Vector3(...b.position).distanceToSquared(point||new T.Vector3())).slice(0,limit);
 async function cached(url){for(let attempt=0;attempt<2;attempt++){if(signal.aborted)throw new DOMException('导览已关闭','AbortError');const controller=new AbortController(),stop=()=>controller.abort();signal.addEventListener('abort',stop,{once:true});let timer;const alive=()=>{clearTimeout(timer);timer=setTimeout(stop,20000);};alive();const deadline=setTimeout(stop,180000);try{const r=await fetch(url,{signal:controller.signal,cache:'force-cache'});if(!r.ok)throw Error('园林资源 HTTP '+r.status);alive();let body;if(r.body&&typeof TransformStream==='function'){const watched=r.body.pipeThrough(new TransformStream({transform(chunk,out){alive();out.enqueue(chunk);}}));body=await new Response(watched).arrayBuffer();}else{clearTimeout(timer);body=await r.arrayBuffer();}return new Response(body,{status:r.status,statusText:r.statusText,headers:r.headers});}catch(error){if(signal.aborted||attempt===1)throw error;}finally{clearTimeout(timer);clearTimeout(deadline);signal.removeEventListener('abort',stop);}}}
