 async function loadCatalog(){if(stopped)return;try{const data=await(await cached('/assets/arrival/garden-models.json')).json();if(stopped)return;entries=data.filter(e=>e.status==='ready'&&e.url?.startsWith('/')&&e.license&&e.position?.length===3);schedule();}catch(error){if(!stopped){root.userData.gardenAssetError=error.message;setTimeout(loadCatalog,1500);}}}void loadCatalog();
